contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(recipient != address(c), "recipient must not be the contract itself; zero-value call would fail");

        uint beforeBal = address(c).balance;

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool zeroReward = !reverted ? true : true;
        // Since beforeBal is 0 and rewardsForA[recipient] is 0 unless bonus was claimed,
        // P must successfully withdraw zero amount to any EOA that accepts Ether.
        // The only general rule in P: for a fresh contract (address(c).balance == 0),
        // a direct withdrawReward call to a non-C address must succeed with no value sent.
        assert(!reverted && address(c).balance == beforeBal);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint bonusEligible) public payable {
        require(recipient != address(c), "recipient must not be C itself");

        // Optionally set up a reward for the recipient through the public entry point.
        if (bonusEligible != 0) {
            c.getFirstWithdrawalBonus(recipient);
        }

        // Fund c so it can pay out any reward.
        if (address(this).balance > 0) {
            (bool ok, ) = address(c).call{value: address(this).balance}("");
            require(ok, "funding C failed");
        }

        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The direct withdrawal must not revert; after it, C's balance is beforeBalance minus the amount paid.
        // Since rewardsForA[recipient] is observable only indirectly, we assert the general invariant:
        // no revert and balance is either unchanged (zero reward) or reduced by the known reward (100 if bonus was set up).
        assert(!reverted && (address(c).balance == beforeBalance || address(c).balance == beforeBalance - 100));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint setupBonus, uint fundAmount) public payable {
        require(recipient != address(c), "recipient must not be C itself");
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Setup: optionally give the recipient a 100-unit reward using the public entry point.
        if (setupBonus != 0) {
            c.getFirstWithdrawalBonus(recipient);
        }

        // Fund C so it can pay out any reward. This is a direct top-level Ether transfer.
        if (fundAmount > 0) {
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent, "funding C failed");
        }

        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        // The deciding call must not revert, and the balance change must be 0 or the known reward amount.
        assert(!reverted && (afterBalance == beforeBalance || afterBalance + 100 == beforeBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient) public payable {
        require(recipient != address(0));

        uint firstBonusBefore = c.rewardsForA(recipient);

        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) { firstReverted = false; } catch { firstReverted = true; }

        if (firstReverted) {
            // If the first call reverted, no bonus should have been recorded.
            assert(c.rewardsForA(recipient) == firstBonusBefore && c.claimedBonus(recipient) == false);
        } else {
            // If the first call succeeded, the recipient is now marked as having claimed the bonus.
            assert(c.claimedBonus(recipient) == true && c.rewardsForA(recipient) == 0);
        }
    }

    receive() external payable {}
}

