    constructor(C _c) {
        c = _c;
    }

    function run(address funder, address recipient, uint amount) public payable {
        require(address(c).balance == 0 || funder != address(0));

        // Give the contract some Ether to pay rewards.
        if (amount > 0) {
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok);
        }

        // Accrue a positive reward for the recipient through the public entry point.
        bool bonusSuccess;
        try c.getFirstWithdrawalBonus(recipient) {
            bonusSuccess = true;
        } catch {
            bonusSuccess = false;
        }

        // If the bonus claimed, the reward for recipient was paid out and is now zero.
        uint balBefore = address(c).balance;

        bool withdrawSuccess;
        try c.withdrawReward(recipient) {
            withdrawSuccess = true;
        } catch {
            withdrawSuccess = false;
        }

        uint balAfter = address(c).balance;

        // General rule: whenever withdrawReward succeeds on a positive reward,
        // the contract balance decreases by exactly that reward amount; on zero
        // reward it either reverts or succeeds with no balance change.
        if (bonusSuccess) {
            // getFirstWithdrawalBonus paid 100 wei to recipient if it succeeded,
            // so any subsequent withdrawReward must revert or move nothing.
            assert(!withdrawSuccess ? balAfter == balBefore : balAfter == balBefore);
        } else {
            // The reward was not claimed, so withdrawReward must revert because
            // the reward for recipient is zero.
            assert(!withdrawSuccess && balAfter == balBefore);
        }
    }

    receive() external payable {}
}

