        try c.getFirstWithdrawalBonus{value: 0}(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: if the second call reverts, then the first call must have succeeded (and therefore claimed the bonus).
        assert(!secondReverted || firstSucceeded);
    }

